            'Payment method: ' => ['Paagi sa pagbayad: ', 'Paraan ng pagbabayad: ', 'Paagi sang pagbayad: '],
            'Payment status: ' => ['Status sa bayad: ', 'Status ng bayad: ', 'Status sang bayad: '],
            'Shipment status: ' => ['Status sa pagpadala: ', 'Status ng pagpapadala: ', 'Status sang pagpadala: '],
            'Which branch do you mean? ' => ['Unsang branch imong pasabot? ', 'Aling branch ang tinutukoy mo? ', 'Ano nga branch ang imo ginatumod? '],
            'Which product do you mean? Examples: ' => ['Unsang produkto imong pasabot? Mga pananglitan: ', 'Aling produkto ang tinutukoy mo? Mga halimbawa: ', 'Ano nga produkto ang imo ginatumod? Mga halimbawa: '],
            'Which component are you choosing, what will you use it for, and what is your budget in PHP?' => ['Unsang component imong gipili, para asa kini, ug pila ang imong budget sa PHP?', 'Aling component ang pipiliin mo, para saan ito, at magkano ang budget mo sa PHP?', 'Ano nga component ang imo ginapili, para sa ano ini, kag pila ang imo budget sa PHP?'],
            'Could you clarify whether you need product information, an order update, branch details, or payment, delivery, cancellation, return or refund guidance?' => ['Palihog klaroha kon produkto, order, branch, pagbayad, delivery, cancellation, return, o refund ang imong pangutana.', 'Linawin kung produkto, order, branch, pagbabayad, delivery, cancellation, return, o refund ang iyong tanong.', 'Palihog klaroha kon produkto, order, branch, pagbayad, delivery, cancellation, return, ukon refund ang imo pamangkot.'],
            'Please tell me which product, branch, order or support question you would like help with.' => ['Unsang produkto, branch, order, o pangutana ang imong kinahanglan og tabang?', 'Aling produkto, branch, order, o tanong ang kailangan mong tulong?', 'Ano nga produkto, branch, order, ukon pamangkot ang imo kinahanglan sang bulig?'],
            'Please provide a product name or model so I can check its current price and Sagay availability.' => ['Ihatag ang ngalan o modelo sa produkto aron masusi ang kasamtangang presyo ug stock sa Sagay.', 'Ibigay ang pangalan o modelo ng produkto para masuri ang kasalukuyang presyo at stock sa Sagay.', 'Ihatag ang ngalan ukon modelo sang produkto agod mausisa ang kasamtangan nga presyo kag stock sa Sagay.'],
            'I could not find an available catalog option matching those constraints. Please provide a component type and budget in PHP.' => ['Walay available nga produkto nga mohaom sa mga kondisyon. Ihatag ang component type ug budget sa PHP.', 'Walang available na produktong pasok sa mga kondisyon. Ibigay ang component type at budget sa PHP.', 'Wala sing available nga produkto nga nagaigo sa mga kondisyon. Ihatag ang component type kag budget sa PHP.'],
            'Please provide the exact catalog names of the parts to compare. I need at least two identified parts and cannot infer a model from a product family.' => ['Ihatag ang eksaktong ngalan sa mga parts sa katalogo. Kinahanglan labing menos duha ka nailhang parts; dili makatag-an og modelo gikan sa product family.', 'Ibigay ang eksaktong pangalan ng parts sa katalogo. Kailangan ng hindi bababa sa dalawang natukoy na parts; hindi mahuhulaan ang modelo mula sa product family.', 'Ihatag ang eksakto nga ngalan sang mga parts sa katalogo. Kinahanglan sang labing menos duha ka nakilala nga parts; indi makatag-an sang modelo halin sa product family.'],
            'More than one part matches the same component type. Please identify one exact catalog model for each part before I check compatibility.' => ['Adunay daghang parts sa parehas nga component type. Ihatag ang usa ka eksaktong modelo matag part sa dili pa susihon ang compatibility.', 'May maraming parts sa parehong component type. Ibigay ang isang eksaktong modelo bawat part bago suriin ang compatibility.', 'May madamo nga parts sa pareho nga component type. Ihatag ang isa ka eksakto nga modelo kada part antes usisaon ang compatibility.'],
            'A selected part has no verified component profile. Compatibility is unknown until its exact specifications are reviewed.' => ['Walay verified component profile ang usa ka part. Unknown ang compatibility hangtod masusi ang eksaktong specifications.', 'Walang verified component profile ang isang part. Unknown ang compatibility hanggang masuri ang eksaktong specifications.', 'Wala sing verified component profile ang isa ka part. Unknown ang compatibility tubtob mausisa ang eksakto nga specifications.'],
            'Historical manual GCash and Maya orders retain their uploaded-proof and staff-review workflow.' => ['Ang daang manual GCash ug Maya orders nagkinahanglan gihapon sa ilang proof-upload ug staff-review workflow.', 'Nananatili ang proof-upload at staff-review workflow ng dating manual GCash at Maya orders.', 'Ang daan nga manual GCash kag Maya orders nagagamit gihapon sang ila proof-upload kag staff-review workflow.'],
            'When manual wallet payment is offered at checkout, follow its proof-upload instructions.' => ['Kung adunay manual wallet payment sa checkout, sunda ang proof-upload instructions niini.', 'Kapag may manual wallet payment sa checkout, sundin ang proof-upload instructions nito.', 'Kon may manual wallet payment sa checkout, sunda ang proof-upload instructions sini.'],
            'Cash (Pay at Pickup) and Debit/Credit Card (Pay at Store) require no upload; staff confirm payment and product handover together.' => ['Walay upload sa Cash (Pay at Pickup) ug Debit/Credit Card (Pay at Store); magkuyog nga kumpirmahon sa staff ang bayad ug paghatag sa produkto.', 'Walang upload sa Cash (Pay at Pickup) at Debit/Credit Card (Pay at Store); sabay na kinukumpirma ng staff ang bayad at pag-abot ng produkto.', 'Wala sing upload sa Cash (Pay at Pickup) kag Debit/Credit Card (Pay at Store); dungan nga ginakumpirma sang staff ang bayad kag paghatag sang produkto.'],
            'COD is delivery-only and requires no upload.' => ['Para lamang sa delivery ang COD ug walay upload.', 'Para lamang sa delivery ang COD at walang upload.', 'Para lamang sa delivery ang COD kag wala sing upload.'],
            'Collection after delivery and full remittance reconciliation are separate; collection alone does not complete payment.' => ['Lahi ang pagkolekta human sa delivery ug full remittance reconciliation; dili makakompleto sa bayad ang pagkolekta lamang.', 'Magkahiwalay ang pagkolekta matapos ang delivery at full remittance reconciliation; hindi nakukumpleto ang bayad sa pagkolekta lamang.', 'Lain ang pagkolekta pagkatapos sang delivery kag full remittance reconciliation; indi makakompleto sang bayad ang pagkolekta lamang.'],
            'Check order details for the latest recorded status.' => ['Tan-awa ang detalye sa order alang sa pinakabag-ong narecord nga status.', 'Tingnan ang detalye ng order para sa pinakabagong naitalang status.', 'Tan-awa ang detalye sang order para sa pinakabag-o nga narecord nga status.'],
            'Please reply with one product name or model, or specify a brand.' => ['Ihatag ang usa ka ngalan sa produkto, modelo, o brand.', 'Ibigay ang isang pangalan ng produkto, modelo, o brand.', 'Ihatag ang isa ka ngalan sang produkto, modelo, ukon brand.'],
        ] as $source => $translations) {
            $replacements[$source] = $translations[$index];
        }

        $placeholders = [];
        $protectedText = [];
        foreach (array_values(array_unique(array_filter($protected, fn ($value): bool => is_string($value) && $value !== ''))) as $position => $value) {
            $placeholder = "\x1F".$position."\x1F";
            $protectedText[$value] = $placeholder;
            $placeholders[$placeholder] = $value;
        }

        return strtr(strtr(strtr($message, $protectedText), $replacements), $placeholders);
    }
}
